// Formulario: POST { email, nombre, asunto, mensaje }
const b = $json.body ?? {};
return {
  json: {
    canal: 'webhook',
    email: String(b.email ?? '').trim(),
    nombre_informado: String(b.nombre ?? '').trim(),
    asunto: String(b.asunto ?? '').trim(),
    pregunta: String(b.mensaje ?? b.pregunta ?? '').trim(),
    gmail_message_id: ''
  }
};

// Gmail (modo completo): from.value[0], subject, text, id
const from = $json.from?.value?.[0] ?? {};
const texto = String($json.text ?? $json.snippet ?? '');
// Se descarta el historial citado para que el agente lea solo el mensaje nuevo
const lineas = [];
for (const l of texto.split(/\r?\n/)) {
  if (/^(El|On) .+(escribió|wrote):\s*$/.test(l.trim())) break;
  if (l.trim().startsWith('>')) continue;
  lineas.push(l);
}
return {
  json: {
    canal: 'email',
    email: String(from.address ?? '').trim(),
    nombre_informado: String(from.name ?? '').trim(),
    asunto: String($json.subject ?? '').trim(),
    pregunta: lineas.join('\n').trim(),
    gmail_message_id: $json.id ?? ''
  }
};

const d = $json;
const email = String(d.email ?? '').trim().toLowerCase();
const pregunta = String(d.pregunta ?? '').trim();
const errores = [];
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errores.push('falta el email o no tiene un formato válido');
if (pregunta.length < 10) errores.push('la consulta es demasiado corta (mínimo 10 caracteres)');
if (pregunta.length > 4000) errores.push('la consulta supera los 4000 caracteres');

const request_id = 'REQ-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
const valido = errores.length === 0;
const base = { ...d, email, pregunta, request_id, fecha: new Date().toISOString(), valido };
if (valido) return { json: base };

return {
  json: {
    ...base,
    decision: 'rechazado',
    estado: 'rechazado_validacion',
    http_status: 400,
    respuesta_usuario: 'No pudimos procesar tu consulta: ' + errores.join('; ') + '. Revisá los datos y volvé a enviarla.',
    error_detalle: errores.join('; ')
  }
};

let req;
try { req = $('¿Entrada válida?').item.json; } catch (e) { req = $('¿Entrada válida?').first().json; }
const emp = $json ?? {};
const activo = String(emp.activo ?? 'SI').trim().toUpperCase() !== 'NO';
const encontrado = Boolean(emp.email) && activo;
const base = {
  ...req,
  nombre: emp.nombre || req.nombre_informado || 'compañero/a',
  area: emp.area || '',
  sede: emp.sede || '',
  empleado_encontrado: encontrado
};
if (encontrado) return { json: base };

return {
  json: {
    ...base,
    decision: 'rechazado',
    estado: 'rechazado_no_registrado',
    http_status: 403,
    respuesta_usuario: `Hola. La dirección ${req.email} no figura en el padrón de empleados activos, por eso no podemos procesar la consulta de forma automática. Si sos parte de la empresa, escribinos desde tu cuenta corporativa.`,
    error_detalle: 'email no encontrado o inactivo en la hoja Empleados'
  }
};

// Agrupa los fragmentos recuperados por consulta y arma el bloque de contexto para el agente.
const UMBRAL = 0.55;     // score mínimo para considerar que el manual cubre la consulta
const MAX_CHARS = 6000;  // tope de contexto para no saturar el modelo local
const consultas = $('¿Empleado registrado?').all(0);
const grupos = consultas.map(() => []);

$input.all().forEach((it, i) => {
  if (!it.json?.document?.pageContent) return;   // ítem vacío (sin resultados)
  const pi = it.pairedItem;
  const idx = Array.isArray(pi) ? (pi[0]?.item ?? 0) : (typeof pi === 'number' ? pi : (pi?.item ?? 0));
  (grupos[idx] ?? grupos[0]).push({ ...it.json, _i: i });
});

const fuenteDe = d => d.document.metadata?.archivo || d.document.metadata?.source || 'manual sin nombre';

return consultas.map((c, k) => {
  const docs = (grupos[k] ?? []).sort((a, b) => (b.score ?? 0) - (a.score ?? 0));
  let usado = 0;
  const bloques = [];
  docs.forEach((d, n) => {
    const t = d.document.pageContent.trim();
    if (usado + t.length > MAX_CHARS) return;
    usado += t.length;
    bloques.push(`[${n + 1}] Fuente: ${fuenteDe(d)} | score: ${(d.score ?? 0).toFixed(2)}\n${t}`);
  });
  const mejor = docs.length ? (docs[0].score ?? 0) : 0;
  return {
    json: {
      ...c.json,
      contexto: bloques.length ? bloques.join('\n\n---\n\n') : '(no se recuperó ningún fragmento de los manuales)',
      fuentes_disponibles: [...new Set(docs.map(fuenteDe))],
      mejor_score: Number(mejor.toFixed(3)),
      contexto_suficiente: mejor >= UMBRAL
    },
    pairedItem: { item: docs[0]?._i ?? 0 }
  };
});

let req;
try { req = $('Combinar datos del empleado').item.json; } catch (e) { req = $('Combinar datos del empleado').first().json; }
const ticket = 'TCK-' + req.request_id.replace('REQ-', '');
return {
  json: {
    ...req,
    decision: 'derivar_humano',
    decision_agente: '(no ejecutado)',
    estado: 'derivado_falla_rag',
    categoria: 'otro',
    prioridad: 'media',
    confianza: 0,
    fuentes: '',
    resumen_ticket: 'Consulta sin procesar por falla del Vector Store: ' + req.pregunta.slice(0, 150),
    motivo_decision: 'Supabase no respondió después de 3 intentos',
    ajustes_validacion: '',
    ticket_id: ticket,
    http_status: 202,
    respuesta_usuario: `Hola ${req.nombre}, recibimos tu consulta pero en este momento no podemos consultar los manuales internos. La registramos con el ticket ${ticket} y una persona de IT te va a contactar.`,
    error_detalle: String($json.error?.message ?? $json.error ?? 'error desconocido en Supabase')
  }
};

