{
  "type": "object",
  "properties": {
    "decision": {
      "type": "string",
      "enum": ["responder", "crear_ticket", "derivar_humano", "fuera_de_alcance"],
      "description": "Acción a ejecutar con la consulta"
    },
    "categoria": {
      "type": "string",
      "description": "Tema de la consulta, por ejemplo: VPN y conexión remota, contraseñas y MFA, impresoras, software, hardware, seguridad, otro"
    },
    "prioridad": {
      "type": "string",
      "enum": ["baja", "media", "alta", "critica"],
      "description": "Urgencia de la consulta"
    },
    "confianza": {
      "type": "number",
      "description": "Seguridad de la decisión, de 0 a 1"
    },
    "fuentes": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Archivos de los manuales usados para responder"
    },
    "respuesta_usuario": {
      "type": "string",
      "description": "Mensaje para el empleado; si la decisión es responder, incluye los pasos y termina con Fuente: <archivo>"
    },
    "resumen_ticket": {
      "type": "string",
      "description": "Resumen para el ticket; vacío si la decisión es responder"
    },
    "motivo_decision": {
      "type": "string",
      "description": "Por qué se tomó esa decisión"
    }
  },
  "required": ["decision", "categoria", "prioridad", "confianza", "fuentes", "respuesta_usuario", "resumen_ticket", "motivo_decision"]
}

