// Llega por la salida de error del agente: Ollama caído, timeout o JSON que el parser no pudo leer.
let req;
try { req = $('Armar contexto').item.json; } catch (e) { req = $('Armar contexto').first().json; }
const ticket = 'TCK-' + req.request_id.replace('REQ-', '');
return {
  json: {
    ...req,
    decision: 'derivar_humano',
    decision_agente: '(error)',
    estado: 'derivado_falla_ia',
    categoria: 'otro',
    prioridad: 'media',
    confianza: 0,
    fuentes: '',
    resumen_ticket: 'El agente no pudo procesar la consulta: ' + req.pregunta.slice(0, 150),
    motivo_decision: 'Error del modelo o salida no parseable después de 2 intentos',
    ajustes_validacion: '',
    ticket_id: ticket,
    http_status: 202,
    respuesta_usuario: `Hola ${req.nombre}, recibimos tu consulta y la registramos con el ticket ${ticket}. Una persona de IT la va a revisar y te va a responder por este mismo medio.`,
    error_detalle: String($json.error?.message ?? $json.error ?? 'respuesta nula del LLM')
  }
};

const req = $('Armar contexto').item.json;
const UMBRAL_CONFIANZA = 0.6;
const DECISIONES = ['responder', 'crear_ticket', 'derivar_humano', 'fuera_de_alcance'];
const CATEGORIAS = ['accesos_y_cuentas', 'vpn_y_red', 'impresoras', 'software', 'hardware', 'seguridad', 'otro'];
const PRIORIDADES = ['baja', 'media', 'alta', 'critica'];

let out = $json.output;
if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { out = null; } }

const problemas = [];
const ajustes = [];
if (!out || typeof out !== 'object') problemas.push('salida del LLM nula o no es JSON');
else {
  if (!DECISIONES.includes(out.decision)) problemas.push(`decisión inválida: ${out.decision}`);
  if (typeof out.respuesta_usuario !== 'string' || out.respuesta_usuario.trim().length < 5) problemas.push('respuesta_usuario vacía');
}

const pasos = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
const usoBusqueda = pasos.some(p => p?.action?.tool === 'buscar_en_manuales');
const textoHerramientas = JSON.stringify(pasos);

const decisionAgente = out?.decision ?? '(nula)';
let decision = problemas.length ? 'derivar_humano' : out.decision;
const confianza = Math.min(1, Math.max(0, Number(out?.confianza) || 0));
const categoria = CATEGORIAS.includes(out?.categoria) ? out.categoria : 'otro';
const prioridad = PRIORIDADES.includes(out?.prioridad) ? out.prioridad : 'media';
// Solo se aceptan fuentes que realmente se recuperaron (evita fuentes inventadas)
const fuentes = (Array.isArray(out?.fuentes) ? out.fuentes : [])
  .filter(f => typeof f === 'string' && (req.fuentes_disponibles.includes(f) || textoHerramientas.includes(f)));

if (decision === 'responder') {
  if (!req.contexto_suficiente && !usoBusqueda) { decision = 'crear_ticket'; ajustes.push('respondió sin contexto suficiente'); }
  else if (!fuentes.length) { decision = 'crear_ticket'; ajustes.push('respondió sin fuentes verificables'); }
  else if (confianza < UMBRAL_CONFIANZA) { decision = 'crear_ticket'; ajustes.push(`confianza baja (${confianza})`); }
}
if (prioridad === 'critica' && decision !== 'fuera_de_alcance' && decision !== 'derivar_humano') {
  decision = 'derivar_humano'; ajustes.push('prioridad crítica: siempre a una persona');
}

const ticket = ['crear_ticket', 'derivar_humano'].includes(decision) ? 'TCK-' + req.request_id.replace('REQ-', '') : '';
const ESTADOS = { responder: 'resuelto_automatico', crear_ticket: 'ticket_abierto', derivar_humano: 'derivado_humano', fuera_de_alcance: 'cerrado_fuera_de_alcance' };
const GENERICOS = {
  crear_ticket: `Hola ${req.nombre}, registramos tu consulta con el ticket ${ticket}. Un técnico de IT la va a revisar y te va a contactar.`,
  derivar_humano: `Hola ${req.nombre}, derivamos tu consulta a una persona de la Mesa de Ayuda (ticket ${ticket}). Te van a contactar a la brevedad.`
};

let respuesta = String(out?.respuesta_usuario ?? '').trim();
if (problemas.length || decision !== decisionAgente) respuesta = GENERICOS[decision] ?? respuesta;
if (ticket && !respuesta.includes(ticket)) respuesta += `\n\nNúmero de ticket: ${ticket}.`;
if (decision === 'responder') respuesta += `\n\nFuente: ${fuentes.join(', ')}. Si esto no lo resuelve, respondé este mensaje y abrimos un ticket.`;

return {
  json: {
    ...req,
    decision,
    decision_agente: decisionAgente,
    estado: ESTADOS[decision],
    categoria,
    prioridad,
    confianza,
    fuentes: fuentes.join(', '),
    resumen_ticket: String(out?.resumen_ticket ?? '').trim() || req.pregunta.slice(0, 150),
    motivo_decision: String(out?.motivo_decision ?? '').trim(),
    ajustes_validacion: [...problemas, ...ajustes].join('; '),
    uso_busqueda_extra: usoBusqueda,
    ticket_id: ticket,
    http_status: 200,
    respuesta_usuario: respuesta,
    error_detalle: problemas.join('; ')
  }
};

